# Ratgeber (nur DE): „Kreditkarte als Student in Deutschland“, Gegenstück zur AT-Seite (gleicher Slug, hreflang-Paar).
# In Deutschland gibt es kaum eigene Studentenkarten; die Vergünstigung hängt am Girokonto (Altersgrenze oder Geldeingang).
# Konditionen kommen live aus den DE-Kartendaten (fee, konto, feeNote, tier, fx, cash). Aufruf aus ratgeber.build('de').
import html
E=lambda s: html.escape(str(s)) if s is not None else ''
TIERN={0:'keine',1:'einzelne Bausteine',2:'mit Reiserücktritt',3:'umfassend',4:'Premium'}

def _tbl(head,rows):
    h=''.join(f'<th>{c}</th>' for c in head)
    b=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)
    return f'<div class="tbl wide"><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>'

# slug | Jung-Bedingung (aus Kontomodell/Preisangabe) | Was nach der Grenze gilt
JUNG=[
 ('commerzbank-young-visa-kreditkarte','0 € im StartKonto: 18 bis 27 Jahre, Schüler, Studierende oder Azubis, regelmäßiger Geldeingang','Umstellung auf ein reguläres Konto- und Kartenmodell; Preis laut Preisverzeichnis'),
 ('dkb-visa-kreditkarte','Girokonto 0 € unter 28 Jahren oder ab 700 € Geldeingang im Monat; die Kreditkarte kostet zusätzlich 2,49 € im Monat','Ohne Geldeingang 4,50 € im Monat fürs Konto'),
 ('dkb-visa-debitkarte','Karte kostenlos zum Girokonto; Konto 0 € unter 28 oder ab 700 € Geldeingang','Ohne Geldeingang 4,50 € im Monat fürs Konto'),
 ('ing-visa-card','Karte im Girokonto enthalten; Konto 0 € unter 28 oder ab 1.000 € Geldeingang im Monat','Ohne Geldeingang 4,90 € im Monat fürs Konto'),
 ('comdirect-visa-kreditkarte','Girokonto 0 € unter 28 in Ausbildung, bei 700 € Geldeingang, 3 Wallet-Zahlungen oder 1 Trade im Monat; Karte 1,90 € im Monat','Ohne Bedingung 4,90 € im Monat fürs Konto'),
 ('consorsbank-credit-card-gold-light','Konto 0 € unter 31 oder ab 700 € Geldeingang; Karte ohne Jahresgebühr','Ohne Geldeingang 4 € im Monat fürs Konto'),
 ('norisbank-mastercard-kreditkarte','Top-Girokonto 0 € unter 30 oder ab 500 € Geldeingang; Karte ohne Jahresgebühr','Ohne Geldeingang 3,90 € im Monat fürs Konto'),
 ('1822direkt-visa-classic-kreditkarte','Konto 0 € unter 30 oder ab 700 € Geldeingang; Karte im 1. Jahr gratis','Karte danach laut Preisangabe; Konto ohne Geldeingang 4,90 € im Monat'),
 ('postbank-mastercard','Unter 26 mit Giro plus 5 € im Jahr; 1. Jahr frei bei Kontoeröffnung','Regulär 29 € im Jahr'),
 ('sparkasse-visa-card-basis','Prepaid, bis zum 21. Geburtstag kostenlos (Beispiel Berliner Sparkasse, je Sparkasse verschieden)','Danach Jahresgebühr laut Sparkasse'),
 ('olb-mastercard-standard','Im smartDialog-Konto bis 25 Jahre 0 €','Konto 7,50 € im Monat inkl. Karte'),
 ('tomorrow-now','Unter 21 „Pay what you want“ 0 bis 4,90 € im Monat, sonst 4,90 € oder bei 500 € Geldeingang','4,90 € im Monat'),
]
GRATIS=['tf-bank-mastercard-gold','advanzia-bank-gebuehrenfrei-mastercard-gold','hanseatic-bank-genialcard','awa7-visa-kreditkarte','deutschland-kreditkarte-classic','bank-norwegian-visa-kreditkarte','consors-finanz-mastercard','n26-standard','revolut-standard','c24-bank-smart','trade-republic-karte','wise-debitkarte']

def register(art,P,best,K,nprv,eur,KM):
    T={c['slug']:c for c in K}
    for s,*_ in JUNG:
        if s not in T: raise SystemExit(f'ratgeber_studenten_de: unbekannte Karte {s}')
    for s in GRATIS:
        if s not in T: raise SystemExit(f'ratgeber_studenten_de: unbekannte Karte {s}')
    def L(slug,label=None): return f'<a class="lnk" href="{P}de/kreditkarten/{slug}/">{E(label or T[slug]["titel"])}</a>'
    def fee(c):
        f=c.get('fee'); t='kostenlos' if f==0 else (f'{eur(f)} €' if f is not None else 'keine Angabe')
        if c.get('fee1') is not None and c.get('fee1')!=f: t+=f' <small>(1. Jahr {"gratis" if c["fee1"]==0 else eur(c["fee1"])+" €"})</small>'
        return t
    def ins(c): return TIERN.get(c.get('tier'),'keine Angabe') if c.get('tier') is not None else 'keine Angabe'
    typ={'Kreditkarte':'Kreditkarte mit Rahmen','Charge':'Charge-Karte','Debit':'Debitkarte','Prepaid':'Prepaid'}
    jung=_tbl(['Karte','Regulärer Preis (Karte bzw. Konto)','Bedingung fürs Gratis-Konto','Nach der Altersgrenze','Reiseversicherung','Zahlung Ausland','Bargeld'],
              [(L(s),fee(T[s]),E(w),E(n),E(ins(T[s])),E(KM.fxT(T[s])),E(KM.cashT(T[s])[:90])) for s,w,n in JUNG])
    gratis=_tbl(['Karte','Typ','Jahresgebühr','Bonitätsprüfung','Zahlung Ausland','Bargeld','Reiseversicherung'],
                [(L(s),E(typ.get(T[s]['typ'],T[s]['typ'])),fee(T[s]),E('ja, Kreditrahmen' if T[s]['typ']=='Kreditkarte' else ('nein, Guthaben' if T[s]['typ'] in ('Debit','Prepaid') else 'ja')),E(KM.fxT(T[s])),E(KM.cashT(T[s])[:90]),E(ins(T[s]))) for s in GRATIS])
    studium=f'{best}studium/'
    art('de','kreditkarte-studenten',
      h1='Kreditkarte als Student in Deutschland: Was du ohne Einkommen bekommst und was nach dem Studium passiert',
      mt='Kreditkarte als Student in Deutschland: SCHUFA, Gratis-Karten, Auslandssemester | Finvallo',
      desc='Kreditkarte im Studium: welche Karten es ohne Einkommen gibt, was die SCHUFA-Prüfung bedeutet, wie die Jung-Konditionen der Banken enden und was fürs Auslandssemester zählt.',
      lede='Echte Studentenkarten gibt es in Deutschland kaum. Die Vergünstigung hängt fast immer am Girokonto: gratis bis 26, 28 oder 30, danach zählt der Geldeingang.',
      kurz=(f'In Deutschland gibt es nur eine Karte, die ausdrücklich für Studierende gedacht ist: die {L("commerzbank-young-visa-kreditkarte")} im StartKonto bis 27. Bei DKB, ING, comdirect, Consorsbank, norisbank und 1822direkt ist nicht die Karte, sondern das Konto bis 28, 30 oder 31 kostenlos, danach nur noch mit 500 bis 1.000 € Geldeingang im Monat. '
            f'Ohne Konto und ohne Altersgrenze gibt es {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-gebuehrenfrei-mastercard-gold")} mit Kreditrahmen und Reiseversicherung, {L("hanseatic-bank-genialcard")} und {L("awa7-visa-kreditkarte")} ohne Versicherung, alle nach SCHUFA-Prüfung; ohne Prüfung die Debitkarten von N26, Revolut, C24, Trade Republic und Wise. '
            f'Die Rangfolge aller Karten für Studierende und junge Leute zeigt die <a class="lnk" href="{studium}">Bestenliste Studium</a>.'),
      secs=[
       ('Drei Fragen, bevor du dich für eine Karte entscheidest','''<div class="prose"><p><b>1. Willst du das Konto wechseln?</b> In Deutschland hängt die Studentenvergünstigung am Girokonto, nicht an der Karte. DKB, ING, comdirect, Consorsbank und norisbank geben ihre Karte nur zum eigenen Konto, und das Konto ist bis zu einer Altersgrenze gratis. Wer sein Konto behalten will, nimmt eine Karte ohne Kontobindung: TF Bank, Advanzia, Hanseatic, awa7, Deutschland-Kreditkarte oder Bank Norwegian buchen per Lastschrift von jedem Konto ab.</p>
<p><b>2. Hast du ein regelmäßiges Einkommen?</b> Echte Kreditkarten mit Kreditrahmen fragen die SCHUFA ab und wollen ein Einkommen sehen. Ohne Einkommen fällt der Rahmen klein aus oder der Antrag wird abgelehnt. Debitkarten (N26, Revolut, C24, Trade Republic, Wise) und Prepaid-Karten brauchen keine Prüfung, weil du nur ausgeben kannst, was auf dem Konto liegt. Für Hotels und Mietwagen reicht das oft nicht, dazu unten mehr.</p>
<p><b>3. Reist du?</b> TF Bank und Advanzia enthalten eine Reiseversicherung mit Reiserücktritt und Auslandskranken, die Gold-Karten der Direktbanken teils ebenfalls. Die Debitkarten der Neobanken in ihrer Gratis-Stufe nicht. Für ein Auslandssemester ist das der Punkt, der am meisten Geld wert ist.</p></div>'''),
       ('Karten mit Jung-Konditionen: wo das Alter zählt','<p class="note">Sortiert nach Konto. „Bedingung“ und „Nach der Altersgrenze“ stammen aus den Kontomodellen und Preisangaben der Anbieter, wie sie in unseren Daten erfasst sind. Die Altersgrenzen gelten fürs Konto; „Regulärer Preis“ ist, was Karte oder Konto ohne Vergünstigung kosten.</p>'+jung+
        f'''<div class="prose"><p>Das Muster ist überall gleich: Das Konto ist gratis, solange du jung bist oder genug Geld eingeht, und die Grenze liegt kurz hinter dem typischen Studienende. Bei DKB und ING sind es 28 Jahre, bei norisbank und 1822direkt 30, bei Consorsbank 31, bei Postbank 26 und beim Commerzbank StartKonto 27. Danach kosten die Konten 3,90 bis 4,90 € im Monat, wenn der Geldeingang unter 500 bis 1.000 € liegt; mit dem ersten Gehalt entfällt die Gebühr meist wieder. Teurer als das Konto ist oft die Karte selbst: Die {L("dkb-visa-kreditkarte")} kostet 2,49 € im Monat, die kostenlose Alternative ist die {L("dkb-visa-debitkarte")}.</p>
<p>Bei den Gebühren im Ausland sind die Jung-Konditionen keine Hilfe: ING und DKB Debit verlangen 2,2 % außerhalb des Euroraums, comdirect Debit 1,75 %, Postbank 2,35 %. Günstig sind hier nur die DKB Visa Kreditkarte, comdirect Visa Kreditkarte und Consorsbank Gold Light mit 0 %.</p>
<p class="note"><a class="lnk" href="{studium}">Bestenliste: alle Karten für Studierende und junge Leute, nach Sternen sortiert →</a></p></div>'''),
       ('Karten ohne Altersgrenze, die trotzdem nichts kosten','<p class="note">Karten ohne Jahresgebühr, die jeder beantragen kann. „Bonitätsprüfung ja“ heißt: Die Bank fragt die SCHUFA ab und prüft das Einkommen, bevor sie einen Kreditrahmen vergibt.</p>'+gratis+
        f'''<div class="prose"><p>Für die meisten Studierenden ist eine Kombination am günstigsten: eine Debitkarte für Alltag und Ausland ({L("c24-bank-smart")}, {L("n26-standard")}, {L("revolut-standard")} oder {L("trade-republic-karte")}, alle ohne Bonitätsprüfung und ohne Auslandseinsatzentgelt) plus eine Gratis-Kreditkarte mit Rahmen für Kaution, Flug und Versicherung. {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-gebuehrenfrei-mastercard-gold")} vergeben den Rahmen nach SCHUFA und Einkommen; ein Werkstudentenjob oder ein regelmäßiger Eingang helfen. Beide verzinsen Bargeld ab dem Buchungstag, Einkäufe sind zinsfrei, wenn du die Rechnung vollständig zahlst.</p>
<p>{L("hanseatic-bank-genialcard")} und {L("awa7-visa-kreditkarte")} sind die Alternative ohne Reiseversicherung: 0 % im Ausland, Bargeld im Ausland kostenlos, im Inland 3,95 €, und eine Teilzahlung, die du ausschalten solltest. Die {L("bank-norwegian-visa-kreditkarte")} hat als einzige Gratis-Karte neben TF Bank und Advanzia einen Reiserücktritt, die Summen kennen wir aber nur aus zweiter Hand.</p></div>'''),
       ('SCHUFA ohne Einkommen: was die Bank prüft und was du tun kannst','''<div class="prose"><p>Jede echte Kreditkarte ist ein Kredit, und vor einem Kredit holt die Bank eine SCHUFA-Auskunft ein und schaut auf dein Einkommen. Studierende haben dabei drei Nachteile: kein oder unregelmäßiges Einkommen, eine kurze Kontohistorie und oft eine Adresse, die sich jedes Jahr ändert. Das führt nicht automatisch zur Ablehnung, aber zu einem kleinen Rahmen, oft 500 bis 1.000 €.</p>
<p>Was hilft: ein Konto mit regelmäßigem Eingang, auch wenn es nur BAföG, Kindergeld, Unterhalt oder der Nebenjob ist; keine offenen Raten, kein Dispo im Minus; die Karte bei der Bank beantragen, bei der das Konto schon länger läuft. Deine SCHUFA-Daten kannst du einmal im Jahr kostenlos abfragen (Datenkopie nach Artikel 15 DSGVO), bevor du einen Antrag stellst. Was die Prüfung genau umfasst, steht im Ratgeber <a href="../kreditkarte-beantragen/">Kreditkarte beantragen</a>; welche Karten es ganz ohne SCHUFA-Abfrage gibt, im Ratgeber <a href="../ohne-bonitaetspruefung/">Kreditkarte ohne SCHUFA</a>.</p>
<p>Zwei Dinge solltest du nicht tun: mehrere Anträge gleichzeitig stellen, weil jede Kreditanfrage bei der SCHUFA vermerkt werden kann, und einen Rahmen nehmen, den du nicht in einem Monat zurückzahlen könntest. Die Teilzahlung bei TF Bank, Advanzia und Hanseatic kostet rund 20 bis 25 % im Jahr; warum sie so teuer ist, erklärt der Ratgeber <a href="../teilzahlung/">Teilzahlung</a>.</p></div>'''),
       ('Auslandssemester: was die Karte können muss',f'''<div class="prose"><p>Fünf Monate Erasmus in Lissabon, Stockholm oder Krakau stellen andere Anforderungen als ein Wochenende in Berlin. Drei Dinge entscheiden:</p><ul>
<li><b>Fremdwährung.</b> In Schweden, Polen, Tschechien, der Schweiz oder Großbritannien zahlst du mit ING, DKB Debit, comdirect Debit oder Postbank 1,75 bis 2,35 % Aufschlag auf jeden Einkauf. Bei 600 € Ausgaben im Monat sind das über fünf Monate 50 bis 70 €. Karten ohne Auslandseinsatzentgelt (TF Bank, Advanzia, Hanseatic, awa7, DKB Visa Kreditkarte, C24, N26, Revolut, Trade Republic) zahlen 0 %. Im Euroraum spielt das keine Rolle.</li>
<li><b>Bargeld.</b> Die Debitkarten der Neobanken heben innerhalb ihrer Kontingente gratis ab, Hanseatic, awa7 und Deutschland-Kreditkarte im Ausland kostenlos, TF Bank und Advanzia gebührenfrei mit Zinsen ab dem Buchungstag. Alle Zahlen stehen im Ratgeber <a href="../bargeld-abheben/">Geld abheben</a>.</li>
<li><b>Reiseversicherung über die ganze Dauer.</b> Die Kartenversicherungen gelten pro Reise 30 bis 120 Tage: Revolut 30, easybank Gold und Eurowings 42, ADAC 45, Sparkasse 56, Openbank 60, Postbank und Commerzbank 62, Advanzia, Deutsche Bank und Miles &amp; More 90, American Express Platinum 120. Ein Semester dauert länger. Du brauchst deshalb eine eigene Auslandskrankenversicherung für Studierende; die Europäische Krankenversicherungskarte deckt im EU-Ausland nur die medizinisch notwendige Versorgung zu den Regeln des Gastlands, keinen Rücktransport. Welche Karte was versichert, steht im Ratgeber <a href="../reiseversicherung/">Reiseversicherung über die Kreditkarte</a>.</li></ul>
<p>Praktisch heißt das: C24, N26 oder Revolut für Alltag und Bargeld, dazu eine Kreditkarte mit Rahmen für die Kaution der Wohnung oder des Mietwagens und als Reserve, und für die Krankenversicherung eine eigene Police über die Semesterdauer.</p></div>'''),
       ('Hotel, Mietwagen, Festival-Ticket: wann eine Debitkarte nicht reicht','''<div class="prose"><p>Debitkarten der Neobanken funktionieren fast überall wie Kreditkarten, mit einer Ausnahme: Wer eine Kaution reservieren will, verlangt oft eine echte Kreditkarte mit Rahmen. Autovermieter lehnen Debit- und Prepaid-Karten häufig ab oder verlangen eine teure Zusatzversicherung; manche Hotels blockieren bei Debitkarten den Betrag sofort auf dem Konto, statt ihn nur zu reservieren. Für den Roadtrip nach dem Semester brauchst du also eine Kreditkarte mit Rahmen, und der Rahmen muss die Kaution abdecken, meist 300 bis 1.500 €. Mit einem 500-Euro-Rahmen wird das knapp. Was die Vermieter genau verlangen, steht im Ratgeber <a href="../mietwagen-kaution/">Mietwagen und Kaution</a>.</p></div>'''),
       ('Die vier Fallen bei Jung-Konditionen','''<div class="prose"><ol>
<li><b>Die Umstellung nach der Altersgrenze.</b> Aus 0 € werden 4,50 oder 4,90 € im Monat fürs Konto, ohne dass du etwas unterschreibst, sobald du 28 oder 30 wirst und der Geldeingang fehlt. Trag dir den Geburtstag ein und prüfe, ob der Geldeingang die Gebühr abfängt.</li>
<li><b>Die Teilzahlung.</b> Kreditkarten mit Rahmen (TF Bank, Advanzia, Hanseatic, awa7, Bank Norwegian) bieten die Teilzahlung an, bei manchen ist sie voreingestellt. Was übrig bleibt, kostet 18 bis 25 % im Jahr. In der App auf „gesamter Betrag“ umstellen.</li>
<li><b>Bargeld mit der Kreditkarte.</b> Bei Charge-Karten der Filialbanken 2 bis 2,5 %, mindestens 5 bis 7,50 €, bei TF Bank und Advanzia Zinsen ab dem ersten Tag. Für Bargeld die Girocard am eigenen Automatenverbund oder die Debitkarte nehmen.</li>
<li><b>Das Konto hinter der Karte.</b> Die Karte allein zu vergleichen reicht nicht: DKB Visa Kreditkarte plus Konto ohne Geldeingang kosten zusammen rund 84 € im Jahr, die Debitkarte zum gleichen Konto 54 €. Bei der Bestenliste zählt deshalb der reguläre Preis von Karte und Konto.</li></ol></div>'''),
       ('Quellen','''<div class="prose"><ul>
<li>Jahresgebühren, Kontomodelle, Altersgrenzen, Gebühren im Ausland, Bargeld und Versicherungsstufen: Preis- und Leistungsverzeichnisse der Anbieter, verlinkt auf jeder Kartenseite; die Werte werden beim Bauen dieser Seite aus den Kartendaten übernommen.</li>
<li>SCHUFA-Datenkopie: Artikel 15 DSGVO (kostenlose Auskunft).</li></ul></div>'''),
      ],
      faq=[
       ('Bekomme ich als Student eine Kreditkarte ohne Einkommen?','Eine echte Kreditkarte mit Rahmen nur nach SCHUFA-Prüfung, und ohne Einkommen fällt der Rahmen klein aus oder der Antrag wird abgelehnt. Ohne Prüfung bekommst du Debitkarten von C24, N26, Revolut, Trade Republic oder Wise und Prepaid-Karten; sie funktionieren im Alltag wie Kreditkarten, aber nicht immer für Kautionen.'),
       ('Welche Kreditkarte ist für Studenten in Deutschland kostenlos?','Ohne Kontobindung und ohne Altersgrenze: TF Bank Mastercard Gold und Advanzia Gebührenfrei Mastercard Gold (mit Reiseversicherung), Hanseatic GenialCard, awa7 Visa und Deutschland-Kreditkarte Classic (ohne). Zum Gratis-Konto: Commerzbank Young Visa im StartKonto bis 27, DKB Visa Debitkarte und ING Visa Card bis 28, Consorsbank Gold Light bis 31, norisbank bis 30.'),
       ('Was passiert mit den Studentenkonditionen nach dem Studium?','Die Konten bleiben gratis, solange genug Geld eingeht: DKB 700 €, ING 1.000 €, Consorsbank und comdirect 700 €, norisbank 500 € im Monat. Fehlt der Eingang nach der Altersgrenze (26 bis 31 je nach Bank), kostet das Konto 3,90 bis 4,90 € im Monat. Das Commerzbank StartKonto endet mit 27.'),
       ('Gibt es in Deutschland eine echte Studenten-Kreditkarte?','Nur die Commerzbank Young Visa Kreditkarte, kostenlos im StartKonto für 18- bis 27-Jährige in Schule, Studium oder Ausbildung. Alle anderen Vergünstigungen laufen über das Girokonto (Altersgrenze oder Geldeingang), nicht über die Karte.'),
       ('Welche Karte ist fürs Auslandssemester am besten?','Außerhalb des Euroraums eine Karte ohne Auslandseinsatzentgelt: C24, N26 oder Revolut für Alltag und Bargeld, dazu TF Bank oder Advanzia als Kreditkarte mit Reiseversicherung. Für die Krankenversicherung reicht keine Karte über ein ganzes Semester (30 bis 120 Tage pro Reise); dafür brauchst du eine eigene Auslandskrankenversicherung.'),
       ('Zählt eine Kreditkarte als Student bei der SCHUFA?','Jede Kreditkarte mit Rahmen wird bei der SCHUFA vermerkt. Das ist kein Nachteil, solange du pünktlich zahlst; es baut eine Historie auf. Mehrere Anträge kurz hintereinander, ein überzogener Dispo oder offene Raten wirken dagegen negativ.'),
       ('Reicht eine Debitkarte für Hotel und Mietwagen?','Für Hotels meistens, wobei manche den Betrag sofort abbuchen statt zu reservieren. Für Mietwagen oft nicht: Viele Vermieter verlangen eine Kreditkarte mit Rahmen für die Kaution von 300 bis 1.500 €.'),
       ('Was ist besser für Studenten: Kreditkarte oder Debitkarte?','Beides, für verschiedene Zwecke. Die Debitkarte (C24, N26, Revolut, DKB oder ING zum Gratis-Konto) für Alltag, Ausland und Bargeld, ohne Bonitätsprüfung und ohne Zinsrisiko. Die Kreditkarte (TF Bank, Advanzia, Hanseatic) für Kaution, Flugbuchung und Reiseversicherung. Wer nur eine will und wenig reist, kommt mit der Debitkarte aus.'),
      ],
      related=['kostenlose-kreditkarte','kreditkarte-beantragen','bargeld-abheben'])
